// Generated by philote from page /horses. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { horses } from "@/lib/api";
import { must } from "@/lib/backend";
import { readHorseCard } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import HorseCard from "@/components/common/horse-card";

export const metadata: Metadata = { title: "Horses" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Horses"}
                content={(className) => (
                    <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                        <Records className={className} />
                    </Suspense>
                )}
            />
        </main>
    );
}

// Records puts every card in one element with the layout's class, so the
// layout decides how the cards are arranged.
async function Records({ className }: { className: string }) {
    await connection();
    const records = await must(horses.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No horses yet."}</p>;
    }
    const items = await Promise.all(records.map(readHorseCard));
    return (
        <div className={className}>
            {items.map((item) => (
                <HorseCard key={item.horse.id} {...item} />
            ))}
        </div>
    );
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
      <div className="mx-auto flex w-full max-w-5xl flex-col gap-6 px-4 py-8 sm:px-6 sm:py-10 lg:py-12">
        <header className="flex flex-col gap-3">
          <div className="flex items-center gap-3">
            <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground">
              <Icons.Heart className="size-5" />
            </span>
            <h1 className="font-heading text-3xl font-bold tracking-tight text-foreground sm:text-4xl">
              {title}
            </h1>
          </div>
          <p className="max-w-2xl text-base text-muted-foreground">
            Browse every horse and find one that catches your eye.
          </p>
        </header>
        <Separator orientation="horizontal" />
        {content(
          "grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5 lg:grid-cols-3 lg:gap-6 [&>*]:h-full"
        )}
      </div>
    );
}
